import {test} from 'node:test';
import assert from 'node:assert/strict';
import {formatDuration} from '../src/format-duration.mjs';
test('zero and padding',()=>assert.equal(formatDuration(0),'00:00:00'));
test('floors subsecond values',()=>assert.equal(formatDuration(1999),'00:00:01'));
test('minutes and hours',()=>assert.equal(formatDuration(3723000),'01:02:03'));
test('hours do not wrap at 24',()=>assert.equal(formatDuration(360000000),'100:00:00'));
test('rejects negative and nonfinite values',()=>{for(const value of [-1,NaN,Infinity,-Infinity])assert.throws(()=>formatDuration(value),RangeError);});
test('does not coerce nonnumbers',()=>{for(const value of ['1000',null,undefined])assert.throws(()=>formatDuration(value),TypeError);});
